import {revised,mutationBody} from './revisions.js';
import {visibleMentionedUserIds} from './mentions.js';
import {integer} from '@crew/shared';
import {AppError,validation} from '@crew/shared';
import {issueInput,issueMatches,issueKey} from '../../../../shared/src/schemas/issue.js';
export const publicLabel=row=>revised({id:row.id,projectId:row.project_id,name:row.name,color:row.color,createdAt:row.created_at,updatedAt:row.updated_at});
export function publicIssue(row) {
  return {
    id:row.id,orgId:row.org_id,projectId:row.project_id,projectKey:row.project_key,
    number:row.number,key:issueKey(row.project_key,row.number),title:row.title,
    description:row.description,statusId:row.status_id,statusName:row.status_name,
    statusCategory:row.status_category,priority:row.priority,assigneeId:row.assignee_id,
    assignee:row.assignee_id?{id:row.assignee_id,name:row.assignee_name,email:row.assignee_email}:null,
    estimate:row.estimate,dueDate:row.due_date,parentId:row.parent_id,createdBy:row.created_by,
    creator:{id:row.created_by,name:row.creator_name},rank:row.rank,
    createdAt:row.created_at,updatedAt:row.updated_at
  };
}
const issueSelect=`SELECT i.*,p.org_id,p.key AS project_key,s.name AS status_name,
  s.category AS status_category,u.name AS assignee_name,u.email AS assignee_email,
  creator.name AS creator_name FROM issues i
  JOIN projects p ON p.id=i.project_id JOIN project_statuses s ON s.id=i.status_id
  LEFT JOIN users u ON u.id=i.assignee_id JOIN users creator ON creator.id=i.created_by`;
export function issueRow(ctx,id) {
  const row=ctx.db.prepare(issueSelect+' WHERE i.id=?').get(id);
  if(!row)throw new AppError('NOT_FOUND','Issue not found',404);
  return row;
}
export function getIssue(ctx,id) {
  const issue=publicIssue(issueRow(ctx,id));
  issue.labels=ctx.db.prepare('SELECT l.* FROM labels l JOIN issue_labels il ON il.label_id=l.id WHERE il.issue_id=? ORDER BY l.name,l.id').all(id).map(publicLabel);
  issue.mentionedUserIds=visibleMentionedUserIds(ctx,issue,issue.description);
  return revised(issue);
}
export function listIssues(ctx,projectId,query={}) {
  if(query.priority!==undefined)integer(query.priority,'priority',{min:0,max:4});
  const parent=query.parentId===undefined?'':query.parentId==='null'?' AND i.parent_id IS NULL':' AND i.parent_id=?';
  const args=[projectId,...(query.parentId!==undefined&&query.parentId!=='null'?[query.parentId]:[])];
  const rows=ctx.db.prepare(issueSelect+' WHERE i.project_id=?'+parent+' ORDER BY i.number DESC,i.id').all(...args);
  return rows.map(row=>getIssue(ctx,row.id)).filter(issue=>issueMatches(issue,query));
}
export function emitIssue(ctx,req,action,before,after) {
  const item=after??before;
  return ctx.bus.emit({actorId:req.user.id,orgId:item.orgId,projectId:item.projectId,
    entityType:'issue',entityId:item.id,action,before:before??null,after:after??null,time:ctx.now()});
}
export function validateIssueReferences(ctx,projectId,input,issueId=null) {
  const {db}=ctx;
  const project=db.prepare('SELECT * FROM projects WHERE id=?').get(projectId);
  if(!project)throw new AppError('NOT_FOUND','Project not found',404);
  if(project.archived)throw new AppError('CONFLICT','Archived projects are read-only',409);
  if(input.statusId!==undefined&&!db.prepare('SELECT 1 FROM project_statuses WHERE id=? AND project_id=?').get(input.statusId,projectId))throw validation({statusId:'Choose a status in this project'});
  if(input.assigneeId&&!ctx.permissions.canProject(input.assigneeId,projectId,'project:read'))throw validation({assigneeId:'Assignee must have access to this project'});
  if(input.parentId){
    const parent=db.prepare('SELECT id,project_id,parent_id FROM issues WHERE id=?').get(input.parentId);
    if(!parent||parent.project_id!==projectId)throw validation({parentId:'Parent must belong to this project'});
    const visited=new Set();
    let current=parent;
    while(current){
      if(current.id===issueId||visited.has(current.id))throw validation({parentId:'An issue cannot be its own ancestor'});
      visited.add(current.id);
      current=current.parent_id?db.prepare('SELECT id,parent_id FROM issues WHERE id=?').get(current.parent_id):null;
    }
  }
  if(input.labelIds)for(const labelId of input.labelIds){
    if(!db.prepare('SELECT 1 FROM labels WHERE id=? AND project_id=?').get(labelId,projectId))throw validation({labelIds:'All labels must belong to this project'});
  }
  return project;
}
export function replaceIssueLabels(ctx,issueId,labelIds) {
  ctx.db.prepare('DELETE FROM issue_labels WHERE issue_id=?').run(issueId);
  const insert=ctx.db.prepare('INSERT INTO issue_labels VALUES (?,?)');
  for(const labelId of labelIds)insert.run(issueId,labelId);
}
export function createIssue(ctx,req,projectId,body) {
  const input=issueInput(body);
  const id=ctx.id(),time=ctx.now();
  const issue=ctx.transaction(()=>{
    const project=validateIssueReferences(ctx,projectId,input);
    const statusId=input.statusId??ctx.db.prepare('SELECT id FROM project_statuses WHERE project_id=? ORDER BY position,id LIMIT 1').get(projectId)?.id;
    if(!statusId)throw validation({statusId:'Configure a project workflow before creating issues'});
    const number=project.next_issue_number;
    ctx.db.prepare('UPDATE projects SET next_issue_number=next_issue_number+1 WHERE id=?').run(projectId);
    const rank=ctx.db.prepare('SELECT COALESCE(MAX(rank),0)+1024 AS rank FROM issues WHERE project_id=? AND status_id=?').get(projectId,statusId).rank;
    ctx.db.prepare(`INSERT INTO issues
      (id,project_id,number,title,description,status_id,priority,assignee_id,estimate,due_date,parent_id,created_by,rank,created_at,updated_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id,projectId,number,input.title,input.description,statusId,input.priority,input.assigneeId,input.estimate,input.dueDate,input.parentId,req.user.id,rank,time,time);
    replaceIssueLabels(ctx,id,input.labelIds);
    return getIssue(ctx,id);
  });
  emitIssue(ctx,req,'created',null,issue);
  return issue;
}
export function updateIssue(ctx,req,id,body) {
  const before=getIssue(ctx,id),input=issueInput(mutationBody(body,before),{partial:true});
  const after=ctx.transaction(()=>{
    validateIssueReferences(ctx,before.projectId,input,id);
    if(input.statusId&&input.statusId!==before.statusId){
      const rank=ctx.db.prepare('SELECT COALESCE(MAX(rank),0)+1024 AS rank FROM issues WHERE project_id=? AND status_id=?').get(before.projectId,input.statusId).rank;
      ctx.db.prepare('UPDATE issues SET rank=? WHERE id=?').run(rank,id);
    }
    const mapping={title:'title',description:'description',statusId:'status_id',priority:'priority',assigneeId:'assignee_id',estimate:'estimate',dueDate:'due_date',parentId:'parent_id'};
    const entries=Object.entries(input).filter(([key])=>key!=='labelIds');
    if(entries.length)ctx.db.prepare(`UPDATE issues SET ${entries.map(([key])=>mapping[key]+'=?').join(',')},updated_at=? WHERE id=?`).run(...entries.map(([,value])=>value),ctx.now(),id);
    else ctx.db.prepare('UPDATE issues SET updated_at=? WHERE id=?').run(ctx.now(),id);
    if(input.labelIds)replaceIssueLabels(ctx,id,input.labelIds);
    return getIssue(ctx,id);
  });
  emitIssue(ctx,req,'updated',before,after);
  return after;
}
export function deleteIssue(ctx,req,id) {
  const before=getIssue(ctx,id);
  validateIssueReferences(ctx,before.projectId,{});
  const children=ctx.db.prepare('SELECT id FROM issues WHERE parent_id=?').all(id).map(row=>getIssue(ctx,row.id));
  ctx.transaction(()=>{
    ctx.db.prepare('UPDATE issues SET updated_at=? WHERE parent_id=?').run(ctx.now(),id);
    ctx.db.prepare('DELETE FROM issues WHERE id=?').run(id);
  });
  for(const child of children)emitIssue(ctx,req,'updated',child,getIssue(ctx,child.id));
  emitIssue(ctx,req,'deleted',before,null);
  return before;
}

import {createIssuePages} from './issue-paging.js';
export const hierarchyAccessLost = page => [401,403,404].includes(page?.error?.status);
export function createIssueHierarchy(load,notify=()=>{}) {
  const pages=new Map(),expanded=new Set();
  let disposed=false,focus=null,wanted=null,focusVersion=0;
  const empty={items:[],cursor:null,loading:true,busy:false,error:null};
  function rows() {
    const result=[],stack=[{parent:null,level:1}];
    while(stack.length) {
      const entry=stack.pop();
      if(entry.issue){result.push(entry);if(expanded.has(entry.issue.id))stack.push({parent:entry.issue.id,level:entry.level+1});continue;}
      const page=pages.get(entry.parent)?.snapshot();
      if(!page||hierarchyAccessLost(page))continue;
      for(let index=page.items.length-1;index>=0;index--)stack.push({issue:page.items[index],parent:entry.parent,level:entry.level});
    }
    return result;
  }
  function snapshot(){return {root:pages.get(null)?.snapshot()??empty,branches:Object.fromEntries([...pages].filter(([id])=>id!==null).map(([id,page])=>[id,page.snapshot()])),expanded:[...expanded],rows:rows(),focus,focusVersion};}
  function publish(){if(disposed)return;const visible=rows();if(!visible.some(row=>row.issue.id===focus))focus=visible[0]?.issue.id??null;notify(snapshot());}
  function move(id){focus=id;focusVersion++;publish();}
  function owner(parent) {
    if(!pages.has(parent)){
      const page=createIssuePages(cursor=>load(parent,cursor),state=>{
        if(disposed||pages.get(parent)!==page)return;
        if(wanted?.parent===parent&&!state.loading&&!state.busy){const next=state.items.find(item=>!wanted.before.has(item.id));wanted=null;if(next){focus=next.id;focusVersion++;}}
        publish();
      });
      pages.set(parent,page);
    }
    return pages.get(parent);
  }
  function collapse(id){
    const visible=rows(),index=visible.findIndex(row=>row.issue.id===id),descendants=new Set();
    for(let n=index+1;n<visible.length&&visible[n].level>visible[index].level;n++)descendants.add(visible[n].issue.id);
    for(const key of [id,...descendants]){expanded.delete(key);pages.get(key)?.dispose();pages.delete(key);}
    if(wanted&&(wanted.parent===id||descendants.has(wanted.parent)))wanted=null;
    if(descendants.has(focus))move(id);else publish();
  }
  async function expand(id,enter=false){
    if(expanded.has(id)){if(enter){const child=pages.get(id)?.snapshot().items[0];if(child)move(child.id);}return;}
    expanded.add(id);const page=owner(id);if(enter)wanted={parent:id,before:new Set()};publish();await page.reload();
  }
  async function more(parent){const page=pages.get(parent);if(!page||page.snapshot().busy||!page.snapshot().cursor)return;wanted={parent,before:new Set(page.snapshot().items.map(item=>item.id))};await page.more();}
  function key(id,key){
    const visible=rows(),index=visible.findIndex(row=>row.issue.id===id);if(index<0)return false;
    if(key==='ArrowDown')move(visible[Math.min(index+1,visible.length-1)].issue.id);
    else if(key==='ArrowUp')move(visible[Math.max(index-1,0)].issue.id);
    else if(key==='Home')move(visible[0].issue.id);
    else if(key==='End')move(visible.at(-1).issue.id);
    else if(key==='ArrowRight')expand(id,true);
    else if(key==='ArrowLeft'){if(expanded.has(id))collapse(id);else if(visible[index].parent)move(visible[index].parent);}
    else return false;
    return true;
  }
  return {snapshot,load:()=>owner(null).reload(),expand,collapse,more,key,focus:move,
    reload(){for(const page of pages.values())page.dispose();pages.clear();expanded.clear();wanted=null;focus=null;publish();return owner(null).reload();},
    dispose(){disposed=true;wanted=null;for(const page of pages.values())page.dispose();pages.clear();expanded.clear();}};
}

import {useEffect,useMemo,useRef,useState} from 'preact/hooks';
import {Button,Empty,Loading,Notice} from '../../components/ui.jsx';
import {createIssueHierarchy,hierarchyAccessLost} from './issue-hierarchy.js';
export function IssueHierarchy({api,projectId,filters}) {
  const [saved,setSaved]=useState(null),tree=useRef(null);
  const owner=useMemo(()=>createIssueHierarchy((parent,cursor)=>api.get('/projects/'+encodeURIComponent(projectId)+'/issues?'+new URLSearchParams({...(parent===null?Object.fromEntries(new URLSearchParams(filters)):{}),parentId:parent??'null',limit:20,...(cursor?{cursor}:{})})),state=>setSaved({owner,state})),[api,projectId,filters]);
  const state=saved?.owner===owner?saved.state:owner.snapshot();
  useEffect(()=>{owner.load();return()=>owner.dispose();},[owner]);
  useEffect(()=>{
    if(state.focusVersion&&state.focus)tree.current?.querySelector('[data-issue-id="'+CSS.escape(state.focus)+'"]')?.focus();
  },[owner,state.focusVersion]);
  function feedback(page,parent) {
    if(!page)return null;
    return <li role="none"><Notice error={page.error}/>{hierarchyAccessLost(page)&&<p>Current access to this branch was lost. Its previously loaded issues are hidden.</p>}{page.loading&&<Loading/>}{!page.loading&&!page.error&&!page.items.length&&<Empty>{parent?'No child issues.':'No root issues match these filters.'}</Empty>}{page.cursor&&!hierarchyAccessLost(page)&&<Button type="button" busy={page.busy} onClick={()=>owner.more(parent)}>Load more {parent?'children':'root issues'}</Button>}{page.error&&<Button type="button" onClick={()=>parent?(owner.collapse(parent),owner.expand(parent)):owner.reload()}>Reload {parent?'branch':'hierarchy'}</Button>}</li>;
  }
  function branch(page,parent=null,level=1) {
    return <ul role={parent?'group':'tree'} aria-label={parent?undefined:'Issue hierarchy'} ref={parent?undefined:tree}>
      {!hierarchyAccessLost(page)&&page.items.map(issue=>{
        const expanded=state.expanded.includes(issue.id),children=state.branches[issue.id];
        return <li role="treeitem" aria-expanded={expanded} aria-level={level} aria-label={issue.key+' '+issue.title} data-issue-id={issue.id} key={issue.id} tabIndex={state.focus===issue.id?0:-1} onFocus={event=>{if(event.target===event.currentTarget&&state.focus!==issue.id)owner.focus(issue.id);}} onKeyDown={event=>{if(event.target!==event.currentTarget)return;if(owner.key(issue.id,event.key))event.preventDefault();else if(event.key==='Enter'){event.currentTarget.querySelector('a').click();event.preventDefault();}}}>
          <div><Button type="button" aria-label={(expanded?'Collapse ':'Expand ')+issue.key} onClick={()=>expanded?owner.collapse(issue.id):owner.expand(issue.id)}>{expanded?'−':'+'}</Button> <a href={'#/issues/'+issue.id}>{issue.key} · {issue.title}</a> <span>{issue.statusName}</span></div>
          {expanded&&children&&branch(children,issue.id,level+1)}
        </li>;
      })}{feedback(page,parent)}
    </ul>;
  }
  return <section aria-label="Project issue hierarchy"><p>Filters select root issues only. Expanded descendants show all direct children, including children outside those filters. Each branch loads independently. Use arrows to explore, Home/End for visible bounds, Enter to open; buttons and links also work directly.</p>{branch(state.root)}<Button type="button" onClick={()=>owner.reload()}>Reload hierarchy</Button></section>;
}

import {IssueHierarchy} from './issue-hierarchy.jsx';
import {Markdown,IssueComments,IssueRelations} from './issue-discussion.jsx';
import {AttachmentsPanel} from './attachments.jsx';
import '../../styles/issues.css';
import {useState,useEffect,useRef} from 'preact/hooks';
import {Page,Notice,Loading,Empty,Button,Field,ConfirmButton} from '../../components/ui.jsx';
import {useScopedLoad} from '../insight/scoped-load.js';
import {priorityLabel,PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {IssueEditor} from './issue-editor.jsx';
import {issueListFilters,relativeDue} from './issue-state.js';
import {WorkPicker,useIssuePages,PageMore} from './issue-controls.jsx';
import {ProjectLabels} from './issue-labels.jsx';
export async function loadIssueContext(api,projectId) {
  return api.get('/projects/'+encodeURIComponent(projectId));
}
function canEdit(context) {return !context.project.archived&&context.permissions.write;}
function useActive() {
  const active=useRef(true);
  useEffect(()=>()=>{active.current=false;},[]);
  return active;
}
export function IssueSummary({issue}) {
  const due=relativeDue(issue.dueDate);
  return <article className="issue-summary">
    <div><a href={'#/issues/'+issue.id}><strong>{issue.key}</strong> {issue.title}</a><p>{issue.statusName} · {priorityLabel(issue.priority)} · {issue.assignee?.name??'Unassigned'}</p></div>
    <div className="issue-tags">{issue.labels.map(label=><span key={label.id} className="label-chip" style={{borderColor:label.color}}>{label.name}</span>)}{issue.estimate!==null&&<span>{issue.estimate} points</span>}{issue.dueDate&&<span className={due.overdue?'overdue':''}>{due.label}</span>}</div>
  </article>;
}
export function Issues(props) {return <IssueList key={props.params.projectId} {...props}/>;}
function IssueList({params,api,navigate}) {
  const active=useActive(),projectId=params.projectId;
  const context=useScopedLoad(projectId,()=>loadIssueContext(api,projectId),[projectId]);
  const [filters,setFilters]=useState({}),[creating,setCreating]=useState(false),[view,setView]=useState('list');
  const serialized=new URLSearchParams(issueListFilters(filters)).toString();
  const list=useIssuePages(api,'/projects/'+encodeURIComponent(projectId)+'/issues?'+serialized);
  function filter(field,value){setFilters(previous=>({...previous,[field]:value}));}
  if(context.loading)return <Loading/>;
  if(context.error)return <Notice error={context.error}/>;
  const {project}=context.data,editable=canEdit(context.data);
  return <Page title={project.key+' issues'} actions={<><a href={'#/projects/'+project.id}>Project</a><a href={'#/projects/'+project.id+'/board'}>Board</a><a href={'#/projects/'+project.id+'/labels'}>Labels</a>{editable&&<Button onClick={()=>setCreating(true)}>New issue</Button>}</>}>
    {project.archived&&<Notice>This project is archived and read-only.</Notice>}
    {creating&&<IssueEditor api={api} {...context.data} onCancel={()=>setCreating(false)} onSave={async body=>{const {issue}=await api.post('/projects/'+project.id+'/issues',body);if(active.current)navigate('/issues/'+issue.id);}}/>}
    <div className="issue-filters" role="search" aria-label="Filter issues">
      <Field label="Search issues" name="q" type="search" value={filters.q??''} onInput={event=>filter('q',event.currentTarget.value)}/>
      <Field label="Status"><select value={filters.statusId??''} onChange={event=>filter('statusId',event.currentTarget.value)}><option value="">All statuses</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
      <WorkPicker api={api} project={project} type="users" label="Filter assignee" value={filters.assigneeId??''} onChange={id=>filter('assigneeId',id)} placeholder="Anyone"/>
      <WorkPicker api={api} project={project} type="labels" label="Filter label" value={filters.labelId??''} onChange={id=>filter('labelId',id)} placeholder="All labels"/>
      <Field label="Priority"><select value={filters.priority??''} onChange={event=>filter('priority',event.currentTarget.value)}><option value="">All priorities</option>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
      <Button type="button" onClick={()=>setFilters({})}>Clear filters</Button>
    </div>
    <div role="group" aria-label="Issue view"><Button type="button" aria-pressed={view==='list'} onClick={()=>setView('list')}>List view</Button><Button type="button" aria-pressed={view==='hierarchy'} onClick={()=>setView('hierarchy')}>Hierarchy view</Button></div>
    {view==='hierarchy'?<IssueHierarchy api={api} projectId={projectId} filters={serialized}/>:<>
    {!list.loading&&(list.items.length?<div className="issue-list">{list.items.map(issue=><IssueSummary key={issue.id} issue={issue}/>)}</div>:!list.error&&<Empty>No issues match these filters.</Empty>)}
    <PageMore list={list} label="issues"/></>}
  </Page>;
}
function ChildIssues({api,issue}) {
  const list=useIssuePages(api,'/projects/'+issue.projectId+'/issues?parentId='+encodeURIComponent(issue.id));
  return <section aria-label="Child issues"><h2>Child issues</h2>{list.items.map(child=><IssueSummary key={child.id} issue={child}/>)}{!list.loading&&!list.error&&!list.items.length&&<Empty>No child issues.</Empty>}<PageMore list={list} label="child issues"/></section>;
}
export function IssueDetail(props) {return <IssueRecord key={props.params.issueId} {...props}/>;}
function IssueRecord({params,api,navigate,user}) {
  const active=useActive();
  const [editing,setEditing]=useState(false),[error,setError]=useState(null);
  const result=useScopedLoad(params.issueId,async()=>{
    const {issue}=await api.get('/issues/'+params.issueId);
    const [context,parent]=await Promise.all([loadIssueContext(api,issue.projectId),issue.parentId?api.get('/issues/'+issue.parentId).then(result=>result.issue):null]);
    return {issue,parent,...context};
  },[params.issueId]);
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const {issue,parent,project}=result.data,editable=canEdit(result.data),due=relativeDue(issue.dueDate);
  async function remove(){try{await api.delete('/issues/'+issue.id);if(active.current)navigate('/projects/'+issue.projectId+'/issues');}catch(error){setError(error);}}
  return <Page title={issue.key+' · '+issue.title} actions={<><a href={'#/projects/'+issue.projectId+'/issues'}>All issues</a>{editable&&!editing&&<Button onClick={()=>setEditing(true)}>Edit issue</Button>}</>}>
    <Notice error={error}/>{project.archived&&<Notice>This project is archived and read-only.</Notice>}
    {editing?<IssueEditor api={api} {...result.data} onCancel={()=>setEditing(false)} onSave={async body=>{await api.patch('/issues/'+issue.id,body);if(active.current){setEditing(false);result.reload();}}}/>:<>
      <section aria-label="Description"><h2>Description</h2><Markdown source={issue.description||'No description yet.'}/></section>
      <dl className="issue-properties"><dt>Status</dt><dd>{issue.statusName}</dd><dt>Priority</dt><dd>{priorityLabel(issue.priority)}</dd><dt>Assignee</dt><dd>{issue.assignee?.name??'Unassigned'}</dd><dt>Estimate</dt><dd>{issue.estimate??'Not estimated'}</dd><dt>Due</dt><dd className={due.overdue?'overdue':''}>{due.label}</dd><dt>Created by</dt><dd>{issue.creator.name}</dd><dt>Created</dt><dd><time dateTime={issue.createdAt}>{new Date(issue.createdAt).toLocaleString()}</time></dd><dt>Updated</dt><dd><time dateTime={issue.updatedAt}>{new Date(issue.updatedAt).toLocaleString()}</time></dd><dt>Parent</dt><dd>{parent?<a href={'#/issues/'+parent.id}>{parent.key} · {parent.title}</a>:'No parent issue'}</dd></dl>
      <section><h2>Labels</h2>{issue.labels.length?issue.labels.map(label=><span className="label-chip" key={label.id} style={{borderColor:label.color}}>{label.name}</span>):<Empty>No labels assigned.</Empty>}</section>
      <ChildIssues api={api} issue={issue}/>
      <IssueRelations issue={issue} project={project} api={api} editable={editable}/>
      <IssueComments issue={{...issue,archived:project.archived}} project={project} api={api} user={user} canAdmin={result.data.permissions.manage}/>
      <AttachmentsPanel api={api} issueId={issue.id}/>
      {editable&&<div className="danger-zone"><ConfirmButton message={'Delete '+issue.key+' permanently?'} onConfirm={remove}>Delete issue</ConfirmButton></div>}
    </>}
  </Page>;
}
export const issueRoutes=[{path:'/projects/:projectId/issues',component:Issues},{path:'/issues/:issueId',component:IssueDetail},{path:'/projects/:projectId/labels',component:ProjectLabels}];
export const issueNavigation=[];
